#include <stdio.h>
#include <stdlib.h>

int compare_desc(const void *pa, const void *pb) {
    int a = *(const int *)pa;
    int b = *(const int *)pb;
    return (b > a) - (b < a);
}

int main(void) {
    int n;
    scanf("%d", &n);
    int v[1000];
    for (int i = 0; i < n; i++) {
        scanf("%d", &v[i]);
    }
    qsort(v, (size_t)n, sizeof v[0], compare_desc);
    for (int i = 0; i < n; i++) {
        printf(i + 1 < n ? "%d " : "%d\n", v[i]);
    }
    return 0;
}

