#include <stdio.h>

void fill_any(void *base, size_t n, size_t size, const void *value) {
    unsigned char *p = base;
    const unsigned char *v = value;
    for (size_t i = 0; i < n * size; i++) {
        p[i] = v[i % size];
    }
}

int main(void) {
    short s[3];
    short seven = 7;
    fill_any(s, 3, sizeof s[0], &seven);
    printf("%d %d %d\n", s[0], s[1], s[2]);
    return 0;
}
